import type { CommentReading, CommentSpan, EscapeSpan, StringSpan } from "../findCommentSpans/index.ts";
/** The address a `url()`'s parentheses hold. */
export type Address = {
    /** True where a quotation mark opens it, whitespace aside: the marks are its own, and what stands behind it inside the parentheses is code. */
    isQuoted: boolean;
    /** The opening quotation mark, or the `)` closing a bare address, outside the comments and strings read inside it — the text's length where no `)` stands. */
    index: number;
    /** The comments standing inside the parentheses, which only a bare address behind whitespace, one behind a name spelled other than `url` or a sign glued to it where the parser reads no `//` of its own, or parentheses Sass reads as code, hold. */
    comments: CommentSpan[];
    /** The strings standing inside such parentheses, quotation marks and all, which are strings wherever comments are read there; a quoted address's own string is none of them, and neither is a mark nothing closes. */
    strings: StringSpan[];
    /** The escapes standing in the code of a bare address, which the walk cannot find itself, the parentheses being one step of it; one inside a comment or a string read there is that span's, one standing in the code of an interpolation is the address's too, and a quoted address holds none of its own. */
    escapes: EscapeSpan[];
};
/**
 * Reads the address a `url()`'s parentheses hold, the one reading the comment walk and the `//`-comment guard both ask.
 *
 * A quotation mark behind the `(`, whitespace aside, makes the parentheses hold code: the string is the address, and a comment written behind it is a comment, which is how Sass reads it and how the plain-CSS tokenizer reads it where the mark stands against the parenthesis. Everything else is a bare address, which the first `)` no escape holds closes, outside the comments, strings and interpolations read below — `postcss-scss` alone counts parentheses there, and no compiler takes the text it thereby reads.
 *
 * The whitespace in front of the mark is {@link OPENS_WITH_QUOTE}'s, which is wider than the tokenizer's: a no-break space, a vertical tab and a line separator part the mark from the parenthesis here and not there. That is the declining side of the reading, since both callers pass a comment over, and Sass reads the comment behind all three.
 *
 * Whitespace of the tokenizer's own behind the `(` makes a block comment inside the parentheses a comment, which the `)` closing them then stands outside of. PostCSS takes the parentheses of a lower-case `url(` as one token wherever the `(` is met by anything but a quotation mark and that whitespace; where whitespace does stand there it takes one all the same, but only while the text to the first `)` holds no break, quotation mark, parenthesis, solidus or backslash — and the opening delimiter of a comment holds a solidus. So a comment written behind that whitespace is a comment to PostCSS, to `postcss-less`, which reads by the same tokenizer, and to Sass; Less prints it as text of the address, so reading it as a comment is what declines a write under all four.
 *
 * The same holds behind a name spelled other than `url`, `URL(`, `u\rl(` or `\75 rl(`, and behind a sign the tokenizer glues to the name, `1/url(` or `,url(`: the tokenizer asks the word it read last for `url` itself and meets these parentheses as those of any call, which a solidus makes code, so a block comment inside them is a comment to it and a write must not enter it. Under `postcss-scss` Sass decides instead, since the parser's comment read where Sass reads an address hid the `//` comment Sass reads behind the address.
 *
 * Wherever a comment is read inside the parentheses, a quotation mark the text closes opens a string, whose comment delimiters and `)` are its text: PostCSS and `postcss-less` read the string in `url( a "/*)" b)` so, and Sass reads it so with or without the whitespace, while `postcss-scss`, which takes the parentheses of `url(` as one token, reads no comment inside the string either. The string is handed back with the comments, since the walk records it as one and a comma inside it is text.
 *
 * Under a parser whose own tokenizer reads `//`, which is `postcss-scss`, the parentheses Sass reads as code rather than as an unquoted address ({@link readsAsSassAddress}) hold comments of both kinds, and the first `)` no comment or string covers closes them. Under that parser an interpolation the text closes is read whole in either kind of parentheses, comments inside it included, so a `)` of a call inside it closes nothing. Less reads an address there, and a block comment read where it reads one would hide a `//` comment of its own, so no other syntax reads Sass's way.
 * @param text - The text holding the call.
 * @param openIndex - Behind the `(`.
 * @param name - The name in front of the `(`, as the text spells it.
 * @param reading - What the syntax makes of a `//` comment.
 * @returns The reading.
 */
export declare function readAddress(text: string, openIndex: number, name: string, reading: CommentReading): Address;
